// CORE GAME LAUNCH ENGINE WITH STABILIZED CONTROLS
// ========================================================
function launchGame(gameId) {
  const game = _0xData.find(g => g.id === gameId);
  if (!game) return;

  const rootUrl = (typeof location !== "undefined" && location.origin)
    ? (location.origin.replace(/\/$/, "") + "/")
    : "https://glaxyias.github.io/";

  function resolveGameSrc() {
    if (game.isEmbedCode && game.jsbin) return String(game.jsbin);
    const raw = String(game.url || "");
    if (/^https?:\/\//i.test(raw)) return raw;
    return rootUrl + raw.replace(/^\.\.\//, "").replace(/^\//, "");
  }

  const gameSrc = resolveGameSrc();
  const homeUrl = rootUrl;
  const safeTitle = String(game.title || "Game")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/"/g, "&quot;");
  const safeSrc = gameSrc.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  const safeSrcJs = gameSrc.replace(/\\/g, "\\\\").replace(/'/g, "\\'");

  try {
    const recent = JSON.parse(localStorage.getItem("nx_recent_games") || "[]");
    const next = [gameId].concat(recent.filter(function (id) { return id !== gameId; })).slice(0, 20);
    localStorage.setItem("nx_recent_games", JSON.stringify(next));
  } catch (e) {}

  // Settings: allow disabling iframes (some Unity/WebGL games break in iframes)
  var useIframe = true;
  try {
    useIframe = localStorage.getItem("nx_use_iframe") !== "false";
  } catch (e) {}
  if (!useIframe) {
    var direct = window.open(gameSrc, "_blank");
    if (!direct) {
      window.location.href = gameSrc;
    }
    return;
  }

    const gameTab = window.open("about:blank", "_blank");
  if (!gameTab) {
    alert("Pop-up blocked! Please allow popups to play games.");
    return;
  }

  gameTab.document.title = "Google Docs";
  gameTab.document.open();
  gameTab.document.write(`<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${safeTitle}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
* { -webkit-user-select: none; user-select: none; box-sizing: border-box; }
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #000; }
iframe { width: 100%; height: 100vh; border: 0; display: block; background: #000; }

#intro-overlay {
  position: fixed; inset: 0; width: 100vw; height: 100vh;
  background: #000; z-index: 99999;
  display: flex; justify-content: center; align-items: center;
  overflow: hidden;
  transition: opacity 0.7s ease, visibility 0.7s ease;
}
#intro-overlay.hide { opacity: 0; visibility: hidden; pointer-events: none; }

.intro-bg {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.012) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.012) 1px, transparent 1px);
  background-size: 60px 60px;
  animation: gridPan 20s linear infinite; z-index: 1;
}
.vignette {
  position: absolute; inset: 0;
  background: radial-gradient(circle, rgba(255,255,255,0.03) 0%, #000 75%);
  z-index: 2; pointer-events: none;
}
.logo-container {
  text-align: center; z-index: 3;
  display: flex; flex-direction: column; align-items: center;
  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  max-width: 520px; padding: 20px;
}
.logo-graphic {
  width: 110px; height: 110px; margin-bottom: 28px; position: relative;
  background: #030303; border: 2px solid #d47a55; border-radius: 12px;
  display: flex; justify-content: center; align-items: center;
  font-size: 2.6rem; font-weight: 800; color: #fff;
  text-shadow: 0 0 15px rgba(255,255,255,0.8);
  box-shadow: 0 0 30px rgba(212,122,85,0.25), inset 0 0 20px rgba(212,122,85,0.15);
  animation: elegantFadeIn 1.2s cubic-bezier(0.22,1,0.36,1) forwards, logoGlowPulse 4s infinite alternate ease-in-out 1.2s;
}
.logo-graphic::before, .logo-graphic::after {
  content: ''; position: absolute; width: 14px; height: 14px; border: 3px solid #e59371;
}
.logo-graphic::before { top: -6px; left: -6px; border-right: none; border-bottom: none; }
.logo-graphic::after { bottom: -6px; right: -6px; border-left: none; border-top: none; }
.logo-text {
  font-size: 2.4rem; font-weight: 900; color: #fff; margin: 0;
  letter-spacing: 14px; text-indent: 14px; text-transform: uppercase;
  text-shadow: 0 0 20px rgba(255,255,255,0.75);
}
.logo-subtitle {
  font-size: 0.7rem; font-weight: 600; letter-spacing: 4px;
  color: #a0a0a5; margin-top: 14px; text-transform: uppercase;
}
.game-loading-title {
  margin-top: 22px; color: #e59371; font-size: 0.85rem; font-weight: 700;
  letter-spacing: 1px;
}
.progress-wrap {
  width: min(320px, 80vw); margin-top: 22px;
}
.progress-track {
  width: 100%; height: 8px; background: #1a1a22; border-radius: 99px;
  overflow: hidden; border: 1px solid #333;
}
.progress-fill {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, #d47a55, #fff, #e59371);
  box-shadow: 0 0 10px rgba(229,147,113,0.6);
  transition: width 0.25s ease;
  border-radius: 99px;
}
.progress-meta {
  display: flex; justify-content: space-between; margin-top: 10px;
  font-family: 'Press Start 2P', monospace; font-size: 9px; color: #00ff9d;
  gap: 8px; flex-wrap: wrap;
}
.progress-meta span { opacity: 0.95; }
.fun-fact {
  margin-top: 28px; max-width: 420px; min-height: 48px;
  font-size: 0.8rem; line-height: 1.45; color: #b8b8c0;
  font-weight: 500; transition: opacity 0.4s ease;
}
.fun-fact strong { color: #e59371; }
.back-btn {
  position: fixed; top: 15px; left: 15px; z-index: 100000;
  background: #0a0a0a; color: #8b00ff; border: 2px solid #8b00ff;
  padding: 8px 14px; font-weight: bold; border-radius: 8px;
  cursor: pointer; text-decoration: none; font-family: system-ui, sans-serif;
  box-shadow: 0 0 12px rgba(139,0,255,0.45);
}
@keyframes gridPan { from { background-position: 0 0; } to { background-position: 60px 60px; } }
@keyframes elegantFadeIn { from { opacity: 0; transform: scale(0.9); } to { opacity: 1; transform: scale(1); } }
@keyframes logoGlowPulse {
  from { box-shadow: 0 0 25px rgba(212,122,85,0.2), inset 0 0 15px rgba(212,122,85,0.15); }
  to { box-shadow: 0 0 45px rgba(212,122,85,0.45), inset 0 0 25px rgba(212,122,85,0.3); }
}
</style>
</head>
<body>
<a href="${homeUrl}" class="back-btn" target="_blank">&larr; Back To Home</a>

<div id="intro-overlay">
  <div class="intro-bg"></div>
  <div class="vignette"></div>
  <div class="logo-container">
    <div class="logo-graphic">Nx</div>
    <h1 class="logo-text">Glaxyias</h1>
    <div class="logo-subtitle">Bringing You Unblocked Games Since 2025</div>
    <div class="game-loading-title">Loading ${safeTitle}</div>
    <div class="progress-wrap">
      <div class="progress-track"><div class="progress-fill" id="prog-fill"></div></div>
      <div class="progress-meta">
        <span id="prog-mb">0 MB / ? MB</span>
        <span id="prog-pct">0%</span>
        <span id="prog-eta">ETA --</span>
      </div>
    </div>
    <div class="fun-fact" id="fun-fact"><strong>Fun fact:</strong> Loading…</div>
  </div>
</div>

<iframe id="nx-game-frame" src="about:blank" allowfullscreen
  sandbox="allow-scripts allow-same-origin allow-forms allow-pointer-lock allow-modals allow-downloads allow-popups"
  allow="pointer-lock *; fullscreen *; gamepad *; autoplay *; keyboard-map *"
  referrerpolicy="no-referrer"></iframe>

<script>
(function () {
  var GAME_SRC = '${safeSrcJs}';
  var fill = document.getElementById('prog-fill');
  var mbEl = document.getElementById('prog-mb');
  var pctEl = document.getElementById('prog-pct');
  var etaEl = document.getElementById('prog-eta');
  var factEl = document.getElementById('fun-fact');
  var overlay = document.getElementById('intro-overlay');
  var frame = document.getElementById('nx-game-frame');

  var FACTS = [
    "The first browser game is often credited to 1990s Java applets — no App Store required.",
    "2048 was made in a weekend and still gets millions of plays.",
    "Many 'HTML5 games' are just one index.html and a pile of JS — like this one.",
    "Chromebooks hate huge Unity WebGL builds. Patience is a skill unlock.",
    "about:blank is empty on purpose — it is a blank canvas for cloaked launches.",
    "Your download speed is the real final boss right now.",
    "Slope is basically endless falling with extra steps.",
    "If a game is over 50 MB, grab a snack. We will wait.",
    "Fun factception: this fun fact is loading while the game loads.",
    "GitHub Pages has no loading bar API — we built our own.",
    "The Nx logo is not a Windows error. Probably.",
    "Unblocked does not mean instant. Physics still applies to bandwidth."
  ];

  var factIdx = 0;
  function rotateFact() {
    if (!factEl) return;
    factEl.style.opacity = '0';
    setTimeout(function () {
      factEl.innerHTML = '<strong>Fun fact:</strong> ' + FACTS[factIdx % FACTS.length];
      factEl.style.opacity = '1';
      factIdx++;
    }, 280);
  }
  rotateFact();
  setInterval(rotateFact, 4500);

  function fmtMB(bytes) {
    if (!isFinite(bytes) || bytes < 0) return '?';
    return (bytes / 1048576).toFixed(2);
  }
  function fmtEta(sec) {
    if (!isFinite(sec) || sec < 0) return '--';
    if (sec < 1) return '<1s';
    if (sec < 60) return Math.ceil(sec) + 's';
    var m = Math.floor(sec / 60);
    var s = Math.ceil(sec % 60);
    return m + 'm ' + s + 's';
  }

  var started = performance.now();
  var lastBytes = 0;
  var lastT = started;
  var speedEma = 0;

  function setProgress(loaded, total, forcedPct) {
    var pct = 0;
    if (typeof forcedPct === 'number') pct = forcedPct;
    else if (total > 0) pct = Math.min(99, (loaded / total) * 100);
    else pct = Math.min(90, (performance.now() - started) / 200); // soft crawl if unknown size
    if (fill) fill.style.width = pct.toFixed(1) + '%';
    if (pctEl) pctEl.textContent = Math.floor(pct) + '%';

    if (mbEl) {
      if (total > 0) mbEl.textContent = fmtMB(loaded) + ' MB / ' + fmtMB(total) + ' MB';
      else mbEl.textContent = fmtMB(loaded) + ' MB / ? MB';
    }

    var now = performance.now();
    var dt = (now - lastT) / 1000;
    if (dt > 0.15 && loaded > lastBytes) {
      var inst = (loaded - lastBytes) / dt;
      speedEma = speedEma ? speedEma * 0.75 + inst * 0.25 : inst;
      lastBytes = loaded;
      lastT = now;
    }
    if (etaEl) {
      if (total > 0 && speedEma > 500) {
        etaEl.textContent = 'ETA ' + fmtEta((total - loaded) / speedEma);
      } else if (pct > 5 && pct < 99) {
        var elapsed = (now - started) / 1000;
        var estTotal = elapsed / (pct / 100);
        etaEl.textContent = 'ETA ' + fmtEta(estTotal - elapsed);
      } else {
        etaEl.textContent = 'ETA --';
      }
    }
  }

  function finish() {
    setProgress(1, 1, 100);
    if (mbEl && mbEl.textContent.indexOf('?') !== -1) {
      mbEl.textContent = 'Ready';
    }
    if (etaEl) etaEl.textContent = 'Done';
    setTimeout(function () {
      if (overlay) overlay.classList.add('hide');
    }, 350);
  }

  // Try real byte progress via fetch (works when CORS allows — GitHub Pages usually does)
  var ctrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
  var timedOut = false;
  var loadTimer = setTimeout(function () {
    timedOut = true;
    // still wait for iframe; keep soft progress
  }, 120000);

  function startIframe() {
    frame.src = GAME_SRC;
    frame.addEventListener('load', function () {
      clearTimeout(loadTimer);
      finish();
    });
  }

  if (window.fetch && GAME_SRC.indexOf('http') === 0) {
    fetch(GAME_SRC, {
      method: 'GET',
      mode: 'cors',
      credentials: 'omit',
      signal: ctrl && ctrl.signal
    }).then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      var total = Number(res.headers.get('Content-Length')) || 0;
      // Note: Content-Length is only the HTML shell; assets load later inside the iframe.
      // We still show real HTML download, then switch to iframe load phase.
      if (!res.body || !res.body.getReader) {
        return res.blob().then(function () {
          setProgress(total || 1, total || 1, 40);
          startIframe();
        });
      }
      var reader = res.body.getReader();
      var loaded = 0;
      function pump() {
        return reader.read().then(function (result) {
          if (result.done) {
            setProgress(loaded, total || loaded, 45);
            startIframe();
            // iframe phase: crawl 45% -> 95% until load
            var phaseStart = performance.now();
            var tick = setInterval(function () {
              if (timedOut) return;
              var p = 45 + Math.min(50, ((performance.now() - phaseStart) / 15000) * 50);
              setProgress(loaded, total || loaded, p);
            }, 300);
            frame.addEventListener('load', function () {
              clearInterval(tick);
            });
            return;
          }
          loaded += result.value.byteLength || 0;
          setProgress(loaded, total);
          return pump();
        });
      }
      return pump();
    }).catch(function () {
      // CORS or network — fall back to iframe only + estimated progress
      startIframe();
      var phaseStart = performance.now();
      var tick = setInterval(function () {
        var p = Math.min(92, ((performance.now() - phaseStart) / 20000) * 92);
        setProgress(0, 0, p);
      }, 300);
      frame.addEventListener('load', function () { clearInterval(tick); });
    });
  } else {
    startIframe();
  }
})();
<\/script>
</body>
</html>`);

  gameTab.document.close();

  function attemptCloseOriginalTab() {
    try {
      const selfWin = window.open(window.location.href, "_self");
      if (selfWin) selfWin.close();
    } catch (e) {}
    try { window.close(); } catch (e) {}
    try {
      if (window.top && window.top !== window) window.top.close();
    } catch (e) {}
    try {
      window.open("", "_self");
      window.close();
    } catch (e) {}
  }
  attemptCloseOriginalTab();
  setTimeout(attemptCloseOriginalTab, 30);
  setTimeout(function () {
    try { window.location.replace("https://www.google.com"); }
    catch (e) { try { window.location.href = "https://www.google.com"; } catch (e2) {} }
  }, 120);
}


function renderLibraryGrid(gamesArray) {
  const gameGrid = document.getElementById("gameGrid");
  if (!gameGrid) return;

  const list = Array.isArray(gamesArray) ? gamesArray : [];
  window.__nxGridSource = list;

  // Tear down previous virtualizer
  if (window.__nxVirtual && typeof window.__nxVirtual.destroy === "function") {
    try { window.__nxVirtual.destroy(); } catch (e) {}
  }
  gameGrid.innerHTML = "";
  const oldBtn = document.getElementById("nx-load-more");
  if (oldBtn) oldBtn.remove();

  if (!list.length) return;

  // Virtual window: only cards near the viewport exist in the DOM
  const GAP = 12;
  const OVERSCAN = 2; // extra rows above/below
  const TARGET_COLS = 4; // preferred columns on desktop
  const MAX_CARD = 148; // keep cards smaller / square

  const scroller = gameGrid.parentElement || document.documentElement;
  const spacer = document.createElement("div");
  spacer.id = "nx-virtual-spacer";
  spacer.style.cssText = "position:relative;width:100%;";
  const windowEl = document.createElement("div");
  windowEl.id = "nx-virtual-window";
  windowEl.style.cssText = "position:absolute;left:0;right:0;top:0;will-change:transform;";
  spacer.appendChild(windowEl);
  gameGrid.appendChild(spacer);

  // Override grid layout while virtualizing — cards positioned absolutely in rows
  gameGrid.style.display = "block";
  gameGrid.style.minHeight = "0";
  gameGrid.style.overflow = "hidden";
  gameGrid.style.boxSizing = "border-box";
  gameGrid.style.width = "100%";

  let cols = 1;
  let rowH = MAX_CARD + GAP;
  let totalRows = 1;
  let raf = 0;
  let lastStart = -1;
  let lastEnd = -1;
  const cardPool = new Map(); // id -> element

  function measure() {
    // clientWidth already excludes scrollbar; subtract a little so the right column is never clipped
    const raw = Math.max(gameGrid.clientWidth || gameGrid.offsetWidth || 600, 200);
    const width = Math.max(raw - 8, 180);
    if (width < 520) cols = 2;
    else if (width < 760) cols = 3;
    else cols = TARGET_COLS;
    // Slightly smaller than full width so they breathe and don't clip
    const colW = (width - GAP * (cols - 1)) / cols;
    window.__nxCardSize = Math.max(96, colW * 0.92);
    totalRows = Math.ceil(list.length / cols) || 1;
    rowH = window.__nxCardSize + GAP;
    // Center the row of smaller cards in the available width
    window.__nxXOff = Math.max(0, (raw - (cols * window.__nxCardSize + (cols - 1) * GAP)) / 2);
    spacer.style.height = (totalRows * rowH) + "px";
  }

  function makeCard(game) {
    const card = document.createElement("div");
    card.className = "game-card";
    card.setAttribute("data-game-id", game.id);
    card.style.cssText = "position:absolute;box-sizing:border-box;margin:0;overflow:hidden;border-radius:14px;";

    const title = String(game.title || "Game");
    if (game.image) {
      const img = document.createElement("img");
      img.className = "game-card-img";
      img.alt = "";
      img.loading = "lazy";
      img.decoding = "async";
      img.style.cssText = "width:100%;height:100%;object-fit:cover;position:absolute;inset:0;";
      img.src = String(game.image);
      card.appendChild(img);
    } else {
      const ph = document.createElement("div");
      ph.className = "game-card-img-placeholder";
      ph.style.cssText = "position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#2a1a40,#12091c);";
      const sp = document.createElement("span");
      sp.textContent = title.substring(0, 2).toUpperCase();
      ph.appendChild(sp);
      card.appendChild(ph);
    }
    const h3 = document.createElement("h3");
    h3.textContent = title;
    h3.style.cssText = "position:absolute;left:0;right:0;top:0;bottom:0;z-index:3;margin:0;padding:10px 12px;display:flex;align-items:center;justify-content:center;font-size:0.82rem;font-weight:800;text-align:center;color:#fff;line-height:1.2;letter-spacing:0.02em;text-shadow:0 1px 3px #000,0 0 10px #000,0 2px 8px #000;background:rgba(0,0,0,0.35);box-sizing:border-box;";
    card.appendChild(h3);
    const desc = document.createElement("div");
    desc.className = "game-desc-overlay";
    desc.textContent = String(game.desc || "");
    card.appendChild(desc);
    card.onclick = function () { launchGame(game.id); };
    return card;
  }

  function getScrollParent(el) {
    let p = el.parentElement;
    while (p && p !== document.body) {
      const st = getComputedStyle(p);
      const oy = st.overflowY;
      if (oy === "auto" || oy === "scroll" || oy === "overlay") return p;
      p = p.parentElement;
    }
    return window;
  }

  const scrollRoot = getScrollParent(gameGrid);

  function scrollTop() {
    return scrollRoot === window
      ? (window.scrollY || document.documentElement.scrollTop || 0)
      : scrollRoot.scrollTop;
  }
  function viewHeight() {
    return scrollRoot === window ? window.innerHeight : scrollRoot.clientHeight;
  }
  function gridOffsetTop() {
    const rect = spacer.getBoundingClientRect();
    if (scrollRoot === window) return rect.top + scrollTop();
    const rootRect = scrollRoot.getBoundingClientRect();
    return rect.top - rootRect.top + scrollRoot.scrollTop;
  }

  function paint() {
    raf = 0;
    measure();
    const width = Math.max(gameGrid.clientWidth || 600, 200);
    const size = window.__nxCardSize || 140;
    const xOff = window.__nxXOff || 0;
    const top = scrollTop();
    const offset = gridOffsetTop();
    const relTop = Math.max(0, top - offset);
    const startRow = Math.max(0, Math.floor(relTop / rowH) - OVERSCAN);
    const endRow = Math.min(totalRows, Math.ceil((relTop + viewHeight()) / rowH) + OVERSCAN);
    if (startRow === lastStart && endRow === lastEnd && windowEl.childElementCount) return;
    lastStart = startRow;
    lastEnd = endRow;

    const needed = new Set();
    for (let row = startRow; row < endRow; row++) {
      for (let c = 0; c < cols; c++) {
        const idx = row * cols + c;
        if (idx >= list.length) break;
        const game = list[idx];
        if (!game) continue;
        needed.add(String(game.id));
        let card = cardPool.get(String(game.id));
        if (!card) {
          card = makeCard(game);
          cardPool.set(String(game.id), card);
          windowEl.appendChild(card);
        }
        card.style.width = size + "px";
        card.style.height = size + "px";
        card.style.transform = "translate(" + (xOff + c * (size + GAP)) + "px," + (row * rowH) + "px)";
        card.style.display = "";
      }
    }
    // recycle offscreen
    cardPool.forEach(function (card, id) {
      if (!needed.has(id)) {
        card.remove();
        cardPool.delete(id);
      }
    });
  }

  function onScroll() {
    if (raf) return;
    raf = requestAnimationFrame(paint);
  }
  function onResize() {
    lastStart = -1;
    onScroll();
  }

  if (scrollRoot === window) {
    window.addEventListener("scroll", onScroll, { passive: true });
  } else {
    scrollRoot.addEventListener("scroll", onScroll, { passive: true });
  }
  window.addEventListener("resize", onResize, { passive: true });

  paint();

  window.__nxVirtual = {
    destroy: function () {
      if (scrollRoot === window) window.removeEventListener("scroll", onScroll);
      else scrollRoot.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
      if (raf) cancelAnimationFrame(raf);
      cardPool.clear();
      gameGrid.style.display = "";
    }
  };
}


function renderFavoritesGrid() {
  const favGrid = document.getElementById('favoritesGrid');
  const emptyMsg = document.getElementById('favorites-empty-msg');
  if (!favGrid) return;

  favGrid.querySelectorAll('.game-card').forEach(c => c.remove());

  if (favoriteGamesList.length === 0) {
    if (emptyMsg) emptyMsg.style.display = 'block';
  } else {
    if (emptyMsg) emptyMsg.style.display = 'none';
    favoriteGamesList.forEach(gameId => {
      const game = _0xData.find(g => g.id === gameId);
      if (game) {
        const card = document.createElement('div');
        card.className = 'game-card';
        card.setAttribute('data-game-id', game.id);

        // Checks for image thumbnail inside favorites list too!
        const imgHTML = game.image 
          ? `<img src="${game.image}" class="game-card-img" alt="${game.title}">` 
          : `<div class="game-card-img-placeholder"><span>${game.title.substring(0, 2).toUpperCase()}</span></div>`;

        card.innerHTML = `
          ${imgHTML}
          <h3>${game.title}</h3>
          <div class="game-desc-overlay">${game.desc}</div>
        `;
        card.onclick = () => launchGame(game.id);
        favGrid.appendChild(card);
      }
    });
  }
}

function initFeaturedModule() {
  const heroTitle = document.getElementById('hero-title');
  const heroDesc = document.getElementById('hero-desc');
  const playFeaturedBtn = document.getElementById('playFeatured');

  if (_0xData.length > 0 && heroTitle) {
    const randomGameSelection = _0xData[Math.floor(Math.random() * _0xData.length)];
    heroTitle.textContent = randomGameSelection.title;
    if (heroDesc) heroDesc.textContent = randomGameSelection.desc;
    if (playFeaturedBtn) {
      playFeaturedBtn.onclick = () => launchGame(randomGameSelection.id);
    }
  }
}

function updateNavActiveState(activeId) {
  ['nav-home', 'nav-games', 'nav-favorites', 'nav-unblockers', 'nav-profile', 'nav-communications', 'nav-terminal', 'nav-assistant'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove('active');
  });
  const currentActive = document.getElementById(activeId);
  if (currentActive) currentActive.classList.add('active');
}

function clearAllViews() {
  const viewElements = [
    document.getElementById('heroSection'),
    document.querySelector('.random-section'),
    document.getElementById('gameGrid'),
    document.getElementById('favoritesGrid'),
    document.getElementById('unblockersSection'),
    document.getElementById('profileSection'),
    document.getElementById('terminalSection'),
    document.getElementById('assistantSection')
  ];

  viewElements.forEach(element => {
    if (element) {
      element.style.setProperty('display', 'none', 'important');
    }
  });
}

function showHomeView() {
  clearAllViews();
  updateNavActiveState('nav-home');

  const heroSection = document.getElementById('heroSection');
  const randomSection = document.querySelector('.random-section');
  const gameGrid = document.getElementById('gameGrid');
  const favGrid = document.getElementById('favoritesGrid');

  if (heroSection) heroSection.style.display = 'flex';
  if (randomSection) randomSection.style.display = 'block';
  if (favGrid) favGrid.style.setProperty('display', 'none', 'important');

  if (gameGrid) {
    gameGrid.style.setProperty('display', 'none', 'important');
  }
  initFeaturedModule();
}

function showAllGamesView() {
  clearAllViews();
  updateNavActiveState('nav-games');

  const gameGrid = document.getElementById('gameGrid');
  const favGrid = document.getElementById('favoritesGrid');

  if (favGrid) favGrid.style.setProperty('display', 'none', 'important');
  if (gameGrid) {
    gameGrid.style.display = 'grid';
    renderLibraryGrid(_0xData);
  }
}

function showFavoritesView() {
  clearAllViews();
  updateNavActiveState('nav-favorites');

  const gameGrid = document.getElementById('gameGrid');
  const favGrid = document.getElementById('favoritesGrid');

  if (gameGrid) gameGrid.style.setProperty('display', 'none', 'important');
  if (favGrid) {
    favGrid.style.display = 'grid';
    renderFavoritesGrid();
  }
}

async function handlePlaceholderView(navId, viewName) {
  clearAllViews();
  updateNavActiveState(navId);

  const viewLower = viewName.toLowerCase();

  if (viewLower === 'assistant') {
    window.location.href = "https://nullai.base44.app";
    return; 
  }

  const targetSectionId = `${viewLower}Section`;
  let customSectionContainer = document.getElementById(targetSectionId);

  if (!customSectionContainer) {
    customSectionContainer = document.createElement('div');
    customSectionContainer.id = targetSectionId;
    customSectionContainer.className = 'custom-view-panel';

    const mainSectionNode = document.querySelector('.main-content .section') || document.querySelector('.main-content');
    if (mainSectionNode) {
      mainSectionNode.appendChild(customSectionContainer);
    }
  }

  customSectionContainer.style.display = 'block';
  customSectionContainer.innerHTML = `<p style="color: #8b00ff; padding: 20px; font-family: sans-serif; font-style: italic; animation: pulse 1.5s infinite;">Mounting filesystem directory node...</p>`;

  try {
    const targetFolder = viewLower === 'terminal' ? 'Terminal' : viewLower;
    const fetchPath = `../${targetFolder}/${viewLower}.html`;

    const response = await fetch(fetchPath);
    if (!response.ok) throw new Error(`Status error ${response.status}`);

    const dynamicCodeContent = await response.text();
    customSectionContainer.innerHTML = dynamicCodeContent;

    attachChatEventListeners();

    // Execute the profile script dynamically if the profile view is loaded
    if (viewLower === 'profile') {
      // Remove the old script if it exists so we get a fresh load
      const existingScript = document.getElementById('profile-dynamic-script');
      if (existingScript) existingScript.remove();

      // Inject and execute the script
      const script = document.createElement('script');
      script.id = 'profile-dynamic-script';
      script.type = 'module';
      // The timestamp trick forces the browser to run it every time instead of using a cached version
      script.src = `../profile/profile.js?v=${Date.now()}`; 
      document.body.appendChild(script);
    }

  } catch (error) {
    console.error(`[System Error] Failed routing structural data for ${viewName}:`, error);
    customSectionContainer.innerHTML = `
      <div style="padding: 20px; font-family: sans-serif; border: 1px dashed rgba(139,0,255,0.4); border-radius: 8px; max-width: 500px; margin: 20px auto; background: rgba(10,10,10,0.8);">
        <h3 style="color: #ff3333; margin-top: 0;">Filesystem Mount Error</h3>
        <p style="color: #ccc; font-size: 14px;">Could not verify source file configuration at location pathway: <code>/${viewLower === 'terminal' ? 'Terminal' : viewLower}/${viewLower}.html</code></p>
        <p style="color: #666; font-size: 12px; margin-bottom: 0;">Verify repository spelling match definitions alignment protocols.</p>
      </div>
    `;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  initializeBase44Chat();

  const isSplashDisabled = localStorage.getItem('disableStudyCloak') === 'true';
  const cloakOverlay = document.getElementById("educational-cloak");

  if (cloakOverlay) {
    if (isSplashDisabled) {
      cloakOverlay.style.display = 'none';
      cloakOverlay.classList.add("hidden");
    } else {
      const timerDisplay = document.querySelector(".timer-subtext-sticky span");
      let timeLeft = 10;
      if (timerDisplay) {
        timerDisplay.textContent = `${timeLeft} seconds.`;
      }

      const countdownInterval = setInterval(() => {
        timeLeft--;
        if (timeLeft > 0) {
          if (timerDisplay) timerDisplay.textContent = `${timeLeft} seconds.`;
        } else {
          clearInterval(countdownInterval);
          cloakOverlay.classList.add("hidden");
          console.log("Overlay container initialization cleared successfully.");
        }
      }, 1000);
    }
  }

  const settingsBtn = document.getElementById('settingsBtn');
  if (settingsBtn) {
    settingsBtn.onclick = (e) => {
      e.preventDefault();

      let modal = document.getElementById('settingsModal');
      if (!modal) {
        modal = document.createElement('div');
        modal.id = 'settingsModal';
        modal.style = "position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(10,10,10,0.95); z-index:999999; display:none; align-items:center; justify-content:center; font-family:sans-serif;";
        document.body.appendChild(modal);
      }

      modal.innerHTML = `
        <div style="background:#0d0d0d; border:2px solid #8b00ff; border-radius:16px; width:90%; max-width:900px; height:80vh; position:relative; box-shadow:0 0 30px rgba(139,0,255,0.3); display:flex; flex-direction:column;">
          <div style="padding: 20px 30px; border-bottom: 1px solid rgba(139,0,255,0.2); display:flex; justify-content:space-between; align-items:center;">
            <h2 style="color:#8b00ff; margin:0;">Control Panel Configuration</h2>
            <button id="closeSettings" style="background:none; border:none; color:#ff3333; font-size:28px; font-weight:bold; cursor:pointer; margin-left:auto;">&times;</button>
          </div>
          <div id="modal-settings-content" style="flex:1; padding:30px; overflow-y:auto; color:#fff;">
            <p style="color:#8b00ff; font-weight:bold;">Loading system template parameters...</p>
          </div>
        </div>
      `;
      modal.style.display = 'flex';

      fetch('../Settings/settings.html')
        .then(res => {
          if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
          return res.text();
        })
        .then(html => {
          const contentDiv = document.getElementById('modal-settings-content');
          if (contentDiv) {
            contentDiv.innerHTML = html;

            const currentTheme = localStorage.getItem('selectedTheme') || 'default';
            const themeCards = contentDiv.querySelectorAll('.theme-card');
            themeCards.forEach(card => {
              if (card.getAttribute('data-theme') === currentTheme) {
                card.style.borderColor = "#8b00ff";
                card.style.background = "rgba(139, 0, 255, 0.15)";
              }
              card.onclick = () => {
                themeCards.forEach(c => {
                  c.style.borderColor = "transparent";
                  c.style.background = "rgba(255,255,255,0.03)";
                });
                card.style.borderColor = "#8b00ff";
                card.style.background = "rgba(139, 0, 255, 0.15)";
                const selected = card.getAttribute('data-theme');
                localStorage.setItem('selectedTheme', selected);

                if (typeof window.applyTheme === 'function') window.applyTheme(selected);
              };
            });

            const splashCheckbox = document.getElementById('toggle-study-cloak');
            if (splashCheckbox) {
              splashCheckbox.checked = localStorage.getItem('disableStudyCloak') === 'true';
              splashCheckbox.onchange = (e) => {
                localStorage.setItem('disableStudyCloak', e.target.checked ? 'true' : 'false');
              };
            }

            const iframeToggle = document.getElementById('toggle-use-iframe');
            if (iframeToggle) {
              // default ON unless explicitly disabled
              iframeToggle.checked = localStorage.getItem('nx_use_iframe') !== 'false';
              iframeToggle.onchange = (e) => {
                localStorage.setItem('nx_use_iframe', e.target.checked ? 'true' : 'false');
              };
            }

            const cloakSelector = document.getElementById('cloakSelector');
            if (cloakSelector) {
              const savedCloak = localStorage.getItem('savedCloak');
              if (savedCloak) cloakSelector.value = savedCloak;
              cloakSelector.onchange = (e) => {
                if (e.target.value === "none") {
                  localStorage.removeItem('savedCloak');
                } else {
                  localStorage.setItem('savedCloak', e.target.value);
                }
              };
            }

            const autoLaunchCheckbox = document.getElementById('toggle-auto-launch');
            const autoLaunchOptionsDiv = document.getElementById('auto-launch-options');
            const autoLaunchEnvSelect = document.getElementById('auto-launch-environment');

            if (autoLaunchCheckbox && autoLaunchOptionsDiv && autoLaunchEnvSelect) {
              const isAutoLaunchOn = localStorage.getItem('autoLaunchEnabled') === 'true';
              autoLaunchCheckbox.checked = isAutoLaunchOn;
              autoLaunchEnvSelect.value = localStorage.getItem('autoLaunchEnv') || 'about:blank';

              if (isAutoLaunchOn) autoLaunchOptionsDiv.style.display = 'block';

              autoLaunchCheckbox.onchange = (e) => {
                localStorage.setItem('autoLaunchEnabled', e.target.checked ? 'true' : 'false');
                autoLaunchOptionsDiv.style.display = e.target.checked ? 'block' : 'none';
              };

              autoLaunchEnvSelect.onchange = (e) => {
                localStorage.setItem('autoLaunchEnv', e.target.value);
              };
            }

            const shortcutInput = document.getElementById('panicShortcut');
            const panicLinkInput = document.getElementById('panicLink');
            const savePanicBtn = document.getElementById('savePanic');

            if (shortcutInput && panicLinkInput && savePanicBtn) {
              const savedPanicKey = localStorage.getItem('panicKey') || 'b';
              const savedPanicBlocker = localStorage.getItem('panicBlocker') || 'goguardian';
              const savedPanicUrl = localStorage.getItem('panicUrl') || 'https://classroom.google.com';

              let tempKey = savedPanicKey;
              shortcutInput.onkeydown = (e) => {
                e.preventDefault();
                if (["Control", "Shift", "Alt", "Meta", "Escape"].includes(e.key)) return;
                tempKey = e.key.toLowerCase();
                shortcutInput.value = `Key: ${e.key.toUpperCase()}`;
              };

              savePanicBtn.onclick = () => {
                localStorage.setItem('panicKey', tempKey);
                localStorage.setItem('panicUrl', panicLinkInput.value.trim());

                savePanicBtn.textContent = "Saved Successfully!";
                savePanicBtn.style.background = "#10b981";
                setTimeout(() => {
                  savePanicBtn.textContent = "Save Panic Settings";
                  savePanicBtn.style.background = "#8b00ff";
                }, 2000);
              };
            }
          }

          const modalCloseBtn = document.getElementById('closeSettings');
          if (modalCloseBtn) {
            modalCloseBtn.onclick = () => { modal.style.display = 'none'; };
          }
        })
        .catch(err => {
          console.error("Modal operational crash trace:", err);
          const contentDiv = document.getElementById('modal-settings-content');
          if (contentDiv) {
            contentDiv.innerHTML = `<p style="color:#ff3333;">Failed parsing setup resources within current active viewport.</p>`;
          }
        });
    };
  }

  showHomeView();

  const randomBtn = document.getElementById('randomBtn');
  if (randomBtn) {
    randomBtn.onclick = () => {
      const idx = Math.floor(Math.random() * _0xData.length);
      launchGame(_0xData[idx].id);
    };
  }

  const user = localStorage.getItem('chatUser');
  if (user) {
    if (document.getElementById('welcome-text')) {
      document.getElementById('welcome-text').textContent = `Hello, ${user}`;
    }
    if (document.getElementById('signInBtn')) {
      document.getElementById('signInBtn').textContent = "Sign Out";
    }
  } else {
    if (document.getElementById('welcome-text')) {
      document.getElementById('welcome-text').textContent = "Hello, Guest";
    }
    if (document.getElementById('signInBtn')) {
      document.getElementById('signInBtn').textContent = "Sign In";
    }
  }

  if (document.getElementById('signInBtn')) {
    document.getElementById('signInBtn').onclick = () => {
      if (localStorage.getItem('chatUser')) {
        localStorage.removeItem('chatUser');
        location.reload();
      } else {
        window.location.href = "../Login/login.html";
      }
    };
  }

  if (document.getElementById('nav-home')) document.getElementById('nav-home').onclick = (e) => { e.preventDefault(); showHomeView(); };
  if (document.getElementById('nav-games')) document.getElementById('nav-games').onclick = (e) => { e.preventDefault(); showAllGamesView(); };
  if (document.getElementById('nav-favorites')) document.getElementById('nav-favorites').onclick = (e) => { e.preventDefault(); showFavoritesView(); };

  if (document.getElementById('nav-unblockers')) document.getElementById('nav-unblockers').onclick = (e) => { e.preventDefault(); handlePlaceholderView('nav-unblockers', 'Unblockers'); };
  if (document.getElementById('nav-profile')) document.getElementById('nav-profile').onclick = (e) => { e.preventDefault(); handlePlaceholderView('nav-profile', 'Profile'); };
  if (document.getElementById('nav-terminal')) document.getElementById('nav-terminal').onclick = (e) => { e.preventDefault(); handlePlaceholderView('nav-terminal', 'Terminal'); };

  if (document.getElementById('nav-assistant')) {
    document.getElementById('nav-assistant').onclick = (e) => {
      e.preventDefault();
      window.location.href = "https://nullai.base44.app";
    }; 
  }

  const commsNavBtn = document.getElementById('nav-communications');
  if (commsNavBtn) {
    commsNavBtn.onclick = (e) => {
      e.preventDefault();
      updateNavActiveState('nav-communications');

      if (localStorage.getItem('chatUser')) {
        window.location.href = "../chat/chat.html";
      } else {
        window.location.href = "../Login/login.html";
      }
    };
  }

  if (document.getElementById('stealthOpener')) {
    document.getElementById('stealthOpener').onclick = (e) => {
      e.preventDefault();
      launchStealthWindow(localStorage.getItem('savedCloak') || 'Google Classroom', localStorage.getItem('autoLaunchEnv') || 'about:blank');
    };
  }

  const searchBar = document.getElementById('searchBar');
  if (searchBar) {
    searchBar.addEventListener('input', (e) => {
      const term = e.target.value.toLowerCase().trim();
      if (!term) { showHomeView(); return; }
      document.getElementById('heroSection').style.display = 'none';
      document.querySelector('.random-section').style.display = 'none';
      if (document.getElementById('favoritesGrid')) document.getElementById('favoritesGrid').style.display = 'none';
      if (document.getElementById('gameGrid')) document.getElementById('gameGrid').style.display = 'grid';
      const hits = _0xData.filter(g => g.title.toLowerCase().includes(term) || g.desc.toLowerCase().includes(term));
      renderLibraryGrid(hits);
    });
  }

  const contextMenu = document.getElementById('custom-context-menu');
  const deleteModal = document.getElementById('delete-modal-overlay');
  const ctxFavorite = document.getElementById('ctx-favorite');
  const ctxDelete = document.getElementById('ctx-delete');

  document.addEventListener('contextmenu', (e) => {
    const card = e.target.closest('.game-card');
    if (card) {
      e.preventDefault();
      contextTargetId = card.getAttribute('data-game-id');

      if (favoriteGamesList.includes(contextTargetId)) {
        ctxFavorite.textContent = "Unfavorite Game";
      } else {
        ctxFavorite.textContent = "Favorite Game";
      }

      if (contextMenu) {
        contextMenu.style.left = `${e.clientX}px`;
        contextMenu.style.top = `${e.clientY}px`;
        contextMenu.style.display = 'block';
      }
    } else {
      if (contextMenu) contextMenu.style.display = 'none';
    }
  });

  document.addEventListener('click', () => { if (contextMenu) contextMenu.style.display = 'none'; });

  if (ctxFavorite) {
    ctxFavorite.onclick = () => {
      if (!contextTargetId) return;
      if (favoriteGamesList.includes(contextTargetId)) {
        favoriteGamesList = favoriteGamesList.filter(id => id !== contextTargetId);
      } else {
        favoriteGamesList.push(contextTargetId);
      }
      localStorage.setItem('nullx_favorites_arr', JSON.stringify(favoriteGamesList));

      const favoritesGrid = document.getElementById('favoritesGrid');
      if (favoritesGrid && favoritesGrid.style.display === 'grid') {
        renderFavoritesGrid();
      }
    };
  }

  if (ctxDelete) {
    ctxDelete.onclick = () => {
      if (contextTargetId && deleteModal) deleteModal.style.display = 'flex';
    };
  }

  const confirmDeleteBtn = document.getElementById('confirm-delete-btn');
  if (confirmDeleteBtn) {
    confirmDeleteBtn.onclick = () => {
      if (contextTargetId) {
        _0xData = _0xData.filter(g => g.id !== contextTargetId);
        favoriteGamesList = favoriteGamesList.filter(id => id !== contextTargetId);
        localStorage.setItem('nullx_favorites_arr', JSON.stringify(favoriteGamesList));
        if (document.getElementById('gameGrid').style.display === 'grid') renderLibraryGrid(_0xData);
        if (document.getElementById('favoritesGrid').style.display === 'grid') renderFavoritesGrid();
        if (deleteModal) deleteModal.style.display = 'none';
      }
    };
  }

  const cancelDeleteBtn = document.getElementById('cancel-delete-btn');
  if (cancelDeleteBtn) {
    cancelDeleteBtn.onclick = () => {
      if (deleteModal) deleteModal.style.display = 'none';
    };
  }

  if (navigator.getBattery) {
    navigator.getBattery().then(battery => {
      function updateBatteryDisplay() {
        const batteryText = document.getElementById('battery-status');
        if (batteryText) {
          const level = Math.round(battery.level * 100);
          const charging = battery.charging ? " (Charging)" : "";
          batteryText.textContent = `Battery: ${level}%${charging}`;
        }
      }
      updateBatteryDisplay();
      battery.addEventListener('levelchange', updateBatteryDisplay);
      battery.addEventListener('chargingchange', updateBatteryDisplay);
    }).catch(err => console.error("Battery access denied:", err));
  }

  function updateClockDisplay() {
    const clockText = document.getElementById('digital-clock');
    if (clockText) {
      const options = { hour: '2-digit', minute: '2-digit', second: '2-digit', timeZoneName: 'short' };
      clockText.textContent = new Date().toLocaleTimeString(undefined, options);
    }
  }
  updateClockDisplay();
  setInterval(updateClockDisplay, 1000);

  if (localStorage.getItem('autoLaunchEnabled') === 'true' && !sessionStorage.getItem('launchedThisSession')) {
    sessionStorage.setItem('launchedThisSession', 'true');
    setTimeout(() => {
      launchStealthWindow(localStorage.getItem('savedCloak') || 'Google Classroom', localStorage.getItem('autoLaunchEnv') || 'about:blank');
    }, 500);
  }

  window.addEventListener('keydown', (e) => {
    const savedPanicKey = localStorage.getItem('panicKey');
    const redirectUrl = localStorage.getItem('panicUrl') || 'https://classroom.google.com';

    if (document.activeElement.tagName === 'INPUT' || document.activeElement.tagName === 'TEXTAREA') return;

    if (savedPanicKey && e.key.toLowerCase() === savedPanicKey.toLowerCase()) {
      e.preventDefault();
      window.location.replace(redirectUrl);
    }
  });
});

async function fetchLiveWeather() {
  try {
    const response = await fetch('https://wttr.in/?format=j1');
    if (!response.ok) throw new Error("Weather stream dropped");

    const data = await response.json();
    const current = data.current_condition[0];
    const area = data.nearest_area[0];

    const tempF = current.temp_F;
    const humidity = current.humidity;
    const city = area.areaName[0].value;

    const tempEl = document.getElementById('live-temp');
    const humidEl = document.getElementById('live-humidity');
    const cityEl = document.getElementById('live-city');

    if (tempEl) tempEl.textContent = `${tempF}°`;
    if (humidEl) humidEl.innerHTML = `<i class="fa-solid fa-droplet"></i> ${humidity}% Humidity`;
    if (cityEl) cityEl.textContent = city;

  } catch (err) {
    console.error("[System Error] Live weather lookup stalled:", err);
    const cityEl = document.getElementById('live-city');
    if (cityEl) cityEl.textContent = "Offline Mode";
  }
}

fetchLiveWeather();

(function initLiveUpdateChecker() {
  let currentVersion = null;
  const CHECK_INTERVAL = 30000;

  async function checkServerVersion() {
    try {
      const response = await fetch(`./version.json?cache-bust=${Date.now()}`);
      if (!response.ok) return;

      const data = await response.json();
      const serverVersion = data.version;

      if (!currentVersion) {
        currentVersion = serverVersion;
        return;
      }

      if (serverVersion > currentVersion) {
        currentVersion = serverVersion;
        showUpdateNotification();
      }
    } catch (err) {
      console.log("[NxOS Sync] Live data stream polling paused.");
    }
  }

  function showUpdateNotification() {
    if (document.getElementById("nxos-update-popup")) return;

    const popup = document.createElement("div");
    popup.id = "nxos-update-popup";
    popup.style.cssText = `
      position: fixed;
      bottom: 25px;
      right: 25px;
      background: #0d0d13;
      border: 1px solid #8b00ff;
      border-radius: 8px;
      padding: 18px 22px;
      box-shadow: 0 0 25px rgba(139, 0, 255, 0.4);
      z-index: 99999;
      font-family: monospace;
      color: #fff;
      display: flex;
      flex-direction: column;
      gap: 12px;
      max-width: 320px;
      animation: slideInNxOS 0.4s ease-out;
    `;

    popup.innerHTML = `
      <div style="display: flex; align-items: center; gap: 10px;">
        <span style="color: #27c93f; animation: blink 1s infinite;">●</span>
        <strong style="color: #8b00ff; letter-spacing: 0.5px;">SYSTEM UPDATE DETECTED</strong>
      </div>
      <div style="color: #aaa; font-size: 13px; line-height: 1.4;">
        New live core files and data layouts have just been pushed to the site.
      </div>
      <div style="display: flex; gap: 10px; margin-top: 5px;">
        <button id="nxos-reload-btn" style="flex: 1; background: #8b00ff; border: none; color: #fff; padding: 8px; border-radius: 4px; font-family: inherit; font-weight: bold; cursor: pointer; transition: 0.2s;">
          Sync & Reload
        </button>
        <button id="nxos-dismiss-btn" style="background: #222; border: 1px solid #444; color: #aaa; padding: 8px 12px; border-radius: 4px; font-family: inherit; cursor: pointer;">
          Dismiss
        </button>
      </div>
    `;

    const style = document.createElement("style");
    style.innerHTML = `
      @keyframes slideInNxOS {
        from { transform: translateY(50px); opacity: 0; }
        to { transform: translateY(0); opacity: 1; }
      }
      @keyframes blink {
        0%, 100% { opacity: 0.3; }
        50% { opacity: 1; }
      }
      #nxos-reload-btn:hover { background: #a333ff !important; box-shadow: 0 0 10px rgba(139,0,255,0.5); }
    `;
    document.head.appendChild(style);
    document.body.appendChild(popup);

    document.getElementById("nxos-reload-btn").addEventListener("click", async () => {
      sessionStorage.clear();

      const targetUrl = window.location.href;

      try {
        // 1. Fetch the main HTML file with headers that instruct the server & browser to bypass cache
        await fetch(targetUrl, {
          headers: {
            'Pragma': 'no-cache',
            'Expires': '-1',
            'Cache-Control': 'no-cache, no-store, must-revalidate',
          },
        });

        // 2. Fetch version.json to clear the cache trace on your version tracking
        await fetch('./version.json', {
          headers: {
            'Pragma': 'no-cache',
            'Expires': '-1',
            'Cache-Control': 'no-cache, no-store, must-revalidate',
          },
        });

        // 3. Perform the in-place page swap
        window.location.replace(targetUrl);
      } catch (e) {
        // Fallback reload if network is interrupted
        window.location.reload();
      }
    });

    document.getElementById("nxos-dismiss-btn").addEventListener("click", () => {
      popup.remove();
    });
  }

  checkServerVersion();
  setInterval(checkServerVersion, CHECK_INTERVAL);
})();

